            "title": "Archive",
            "description": "An OpenTok Archive",
            "type": "object",
            "properties": {
                "createdAt": {
                    "type": "integer"
                },
                "duration": {
                    "type": "integer",
                    "minimum": 0
                },
                "id": {
                    "type": "string",
                    "pattern": "^[a-z0-9]{8}-[a-z0-9]{4}-[a-z0-9]{4}-[a-z0-9]{4}-[a-z0-9]{12}$"
                },
                "name": {
