                },
                "reason": {
                    "type": "string"
                },
                "sessionId": {
                    "type": "string"
                },
                "size": {
                    "type": "integer",
                    "minimum": 0
                },
                "status": {
                    "type": "string",
                    "enum": [
                        "available",
                        "started",
                        "stopped",
                        "failed",
                        "deleted",
                        "uploaded",
                        "expired",
                        "paused"
                    ]
                },
                "url": {
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "hasVideo": {
                    "type": "boolean"
                },
                "hasAudio": {
                    "type": "boolean"
                }
            },
            "required": [
                "id",
                "partnerId",
                "sessionId",
                "status"
            ]
