                                "COUNT"
                            ]
                        }
                    }
                },
                {
                    "properties": {
                        "aggregateId": {
                            "enum": [
                                "FIRST_SEEN"
                            ]
                        }
                    }
                },
                {
                    "properties": {
                        "aggregateId": {
                            "enum": [
                                "FIRST_VALUE"
                            ]
                        },
                        "aggregateRules": {
                            "$ref": "#/definitions/singleFieldAggregate"
                        }
                    }
                },
